CREATE   PROCEDURE [synapse_ce].[usp_Insert_listmember]
AS
BEGIN
	INSERT INTO [synapse_ce].[listmember]
	(
			[Id],
			[SinkCreatedOn],
			[SinkModifiedOn],
			[createdby],
			[createdby_entitytype],
			[createdonbehalfby],
			[createdonbehalfby_entitytype],
			[entityid],
			[entityid_entitytype],
			[listid],
			[listid_entitytype],
			[modifiedby],
			[modifiedby_entitytype],
			[modifiedonbehalfby],
			[modifiedonbehalfby_entitytype],
			[ownerid],
			[ownerid_entitytype],
			[createdbyname],
			[createdbyyominame],
			[createdon],
			[createdonbehalfbyname],
			[createdonbehalfbyyominame],
			[entityidtypecode],
			[entitytype],
			[importsequencenumber],
			[listmemberid],
			[modifiedbyname],
			[modifiedbyyominame],
			[modifiedon],
			[modifiedonbehalfbyname],
			[modifiedonbehalfbyyominame],
			[name],
			[overriddencreatedon],
			[owneridtype],
			[owningbusinessunit],
			[owninguser]
	)
	SELECT 
		stg.[Id],
		stg.[SinkCreatedOn],
		stg.[SinkModifiedOn],
		stg.[createdby],
		stg.[createdby_entitytype],
		stg.[createdonbehalfby],
		stg.[createdonbehalfby_entitytype],
		stg.[entityid],
		stg.[entityid_entitytype],
		stg.[listid],
		stg.[listid_entitytype],
		stg.[modifiedby],
		stg.[modifiedby_entitytype],
		stg.[modifiedonbehalfby],
		stg.[modifiedonbehalfby_entitytype],
		stg.[ownerid],
		stg.[ownerid_entitytype],
		stg.[createdbyname],
		stg.[createdbyyominame],
		stg.[createdon],
		stg.[createdonbehalfbyname],
		stg.[createdonbehalfbyyominame],
		stg.[entityidtypecode],
		stg.[entitytype],
		stg.[importsequencenumber],
		stg.[listmemberid],
		stg.[modifiedbyname],
		stg.[modifiedbyyominame],
		stg.[modifiedon],
		stg.[modifiedonbehalfbyname],
		stg.[modifiedonbehalfbyyominame],
		stg.[name],
		stg.[overriddencreatedon],
		stg.[owneridtype],
		stg.[owningbusinessunit],
		stg.[owninguser]
	FROM [staging_ce].[listmember] stg
		LEFT JOIN [synapse_ce].[listmember] tgt
			ON tgt.[id] = stg.[id]
	WHERE tgt.[id] IS NULL

END
